"""Tests for snake.engine.Game class."""

import pytest
from snake.engine import Game


class TestGameInitialization:
    """Test Game initialization and basic properties."""

    @pytest.mark.parametrize(
        ("width", "height", "seed"),
        [
            (10, 10, 0),
            (20, 15, 42),
            (100, 50, 9999),
            (1, 1, 1),
        ],
    )
    def test_init_sets_dimensions(self, width: int, height: int, seed: int):
        """Game stores the width and height given to init."""
        game = Game(width, height, seed)
        assert game.width == width
        assert game.height == height

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_init_snake_initial_position(self, width: int, height: int):
        """Snake starts 3 cells long with head at center, body extending left."""
        game = Game(width, height, seed=0)
        expected_head_x = width // 2
        expected_head_y = height // 2
        assert game.snake[0] == (expected_head_x, expected_head_y)

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_init_snake_initial_length(self, width: int, height: int):
        """Snake starts with exactly 3 cells."""
        game = Game(width, height, seed=0)
        assert len(game.snake) == 3

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_init_snake_extends_left(self, width: int, height: int):
        """Snake body extends left from head (lower x values)."""
        game = Game(width, height, seed=0)
        assert len(game.snake) >= 2
        assert game.snake[1][0] < game.snake[0][0]

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_init_snake_moves_right(self, width: int, height: int):
        """Snake initially moves right (positive x direction)."""
        game = Game(width, height, seed=0)
        for i in range(1, len(game.snake)):
            assert game.snake[0][0] > game.snake[i][0]

    @pytest.mark.parametrize(
        ("width", "height", "seed"),
        [
            (10, 10, 0),
            (20, 15, 42),
            (5, 5, 999),
        ],
    )
    def test_init_food_on_free_cell(self, width: int, height: int, seed: int):
        """Food is placed on a free cell (not on snake body)."""
        game = Game(width, height, seed)
        food = game.food
        assert food is not None
        assert food[0] >= 0 and food[0] < width
        assert food[1] >= 0 and food[1] < height
        assert food not in game.snake


