class TestTickMovement:
    """Test tick() behavior for snake movement and food consumption."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_tick_moves_snake(self, width: int, height: int):
        """tick() moves the snake one cell forward."""
        game = Game(width, height, seed=0)
        initial_head = game.snake[0]
        game.turn("right")
        game.tick()
        new_head = game.snake[0]
        assert new_head != initial_head

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_tick_food_adds_score(self, width: int, height: int):
        """Moving onto food adds 10 to score."""
        game = Game(width, height, seed=0)
        initial_score = game.score
        if game.food is not None:
            food_x, food_y = game.food
            game.snake = [(food_x - 1, food_y), (food_x - 2, food_y), (food_x - 3, food_y)]
        game.turn("right")
        game.tick()
        assert game.score == initial_score + 10

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_tick_food_grows_snake(self, width: int, height: int):
        """Moving onto food grows the snake by one cell."""
        game = Game(width, height, seed=0)
        initial_length = len(game.snake)
        if game.food is not None:
            food_x, food_y = game.food
            game.snake = [(food_x - 1, food_y), (food_x - 2, food_y), (food_x - 3, food_y)]
        game.turn("right")
        game.tick()
        assert len(game.snake) == initial_length + 1

    @pytest.mark.parametrize(
        ("width", "height"),
        [(10, 10), (20, 15)],
    )
    def test_tick_new_food_appears(self, width: int, height: int):
        """After eating food, new food appears on a free cell."""
        game = Game(width, height, seed=0)
        if game.food is not None:
            food_x, food_y = game.food
            game.snake = [(food_x - 1, food_y), (food_x - 2, food_y), (food_x - 3, food_y)]
        initial_food = game.food
        game.turn("right")
        game.tick()
        new_food = game.food
        assert new_food is not None


