"""Tests for snake.render.render function.

This module verifies the render function produces correctly formatted ASCII
art frames with proper dimensions, border characters, and game elements
(positioned according to board coordinates).
"""

import pytest
from snake.engine import Game
from snake.render import render


class TestRenderDimensions:
    """Test that rendered frame has correct dimensions."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
            (5, 5),
            (1, 1),
            (50, 30),
        ],
    )
    def test_returns_list_of_correct_length(self, width: int, height: int):
        """Render returns exactly height + 2 strings."""
        game = Game(width, height, seed=0)
        frame = render(game)
        assert len(frame) == height + 2

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
            (5, 5),
            (1, 1),
            (50, 30),
        ],
    )
    def test_each_string_is_width_plus_2_chars(self, width: int, height: int):
        """Each string in frame is exactly width + 2 characters long."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for row in frame:
            assert len(row) == width + 2

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_all_strings_same_length(self, width: int, height: int):
        """All strings in the frame have equal length."""
        game = Game(width, height, seed=0)
        frame = render(game)
        lengths = [len(row) for row in frame]
        assert len(set(lengths)) == 1


class TestBorderCharacters:
    """Test that border characters appear at correct positions."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
            (5, 5),
        ],
    )
    def test_top_row_is_full_border(self, width: int, height: int):
        """Top row contains only border characters."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for char in frame[0]:
            assert char in "┌─┐"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
            (5, 5),
        ],
    )
    def test_bottom_row_is_full_border(self, width: int, height: int):
        """Bottom row contains only border characters."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for char in frame[-1]:
            assert char in "└─┘"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_left_column_is_vertical_borders(self, width: int, height: int):
        """First column contains vertical border characters."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for row in frame[1:-1]:
            assert row[0] in "│"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_right_column_is_vertical_borders(self, width: int, height: int):
        """Last column contains vertical border characters."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for row in frame[1:-1]:
            assert row[-1] in "│"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_corners_are_corner_chars(self, width: int, height: int):
        """Corners use appropriate corner border characters."""
        game = Game(width, height, seed=0)
        frame = render(game)
        assert frame[0][0] == "┌"
        assert frame[0][-1] == "┐"
        assert frame[-1][0] == "└"
        assert frame[-1][-1] == "┘"


class TestSnakeRendering:
    """Test that snake segments are rendered at correct positions."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_head_at_first_segment_position(self, width: int, height: int):
        """Snake head '@' appears at game.snake[0] position."""
        game = Game(width, height, seed=0)
        frame = render(game)
        head_x, head_y = game.snake[0]
        assert frame[head_y + 1][head_x + 1] == "@"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_body_segments_not_head(self, width: int, height: int):
        """Snake body segments use filled box character."""
        game = Game(width, height, seed=0)
        frame = render(game)
        for segment in game.snake[1:]:
            x, y = segment
            assert frame[y + 1][x + 1] == "█"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_snake_head_not_overwritten_by_body(self, width: int, height: int):
        """Head character '@' is distinct from body character."""
        game = Game(width, height, seed=0)
        frame = render(game)
        head_x, head_y = game.snake[0]
        assert frame[head_y + 1][head_x + 1] == "@"


class TestFoodRendering:
    """Test that food is rendered at correct position."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_food_character_at_position(self, width: int, height: int):
        """Food '○' appears at game.food position when food exists."""
        game = Game(width, height, seed=0)
        if game.food is None:
            pytest.skip("Board is full, no food to render")
        frame = render(game)
        food_x, food_y = game.food
        assert frame[food_y + 1][food_x + 1] == "○"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_no_food_character_when_food_none(self, width: int, height: int):
        """No food character when game.food is None."""
        game = Game(width, height, seed=0)
        game.food = None
        frame = render(game)
        for row in frame[1:-1]:
            for char in row[1:-1]:
                assert char != "○"

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_settable_food_none(self, width: int, height: int):
        """Food can be set to None and render shows no food."""
        game = Game(width, height, seed=0)
        initial_food = game.food
        game.food = None
        frame = render(game)
        assert game.food is None


class TestEmptyCells:
    """Test that empty cells show space character."""

    @pytest.mark.parametrize(
        ("width", "height"),
        [
            (10, 10),
            (20, 15),
        ],
    )
    def test_empty_cells_are_spaces(self, width: int, height: int):
        """Cells not containing snake or food are spaces."""
        game = Game(width, height, seed=0)
        frame = render(game)

        # Create set of occupied positions (board interior only)
        occupied = set()
        for x, y in game.snake:
            occupied.add((x, y))
        if game.food is not None:
            occupied.add(game.food)

        # Check all non-border cells
        for y in range(height):
            for x in range(width):
                if (x, y) not in occupied:
                    assert frame[y + 1][x + 1] == " "


